//! Deadline queue shared by the rights' forfeit and cleanup sweeps.
//!
//! The queue groups entries by their UTC deadline day, counted from the Unix epoch.
//! A bitmap trie finds the earliest day. A cursor records where the next block must resume unfinished work.
//! A contract keeps the columns and exposes them through an adapter generated by
//! [`impl_expiry_queue!`](crate::impl_expiry_queue).

use alloy_primitives::{keccak256, B256, U256};

pub use crate::daily_sweep::Progress;
use crate::error::{PrecompileError, Result, SweepFailure};
use crate::math::constants::MAX_BIN_ID;
use crate::math::tree_math::{self, BinTreeStorage};
use crate::storage::dsl::{Map, Value};
use crate::storage::types::{Storable, StorageKey};
use crate::storage::StorageHandle;
use crate::sweep_budget::{BlockAllowance, SweepBudget};
use crate::time::SECONDS_PER_DAY;

mod walk;
pub use walk::{sweep_through, SweepTime};

/// A queue entry cannot use zero because zero marks a vacant slot.
pub trait QueueEntry: Copy + PartialEq + Storable + StorageKey {
    fn is_vacant(&self) -> bool;
}

impl QueueEntry for U256 {
    fn is_vacant(&self) -> bool {
        self.is_zero()
    }
}

impl QueueEntry for B256 {
    fn is_vacant(&self) -> bool {
        self.is_zero()
    }
}

impl QueueEntry for u64 {
    fn is_vacant(&self) -> bool {
        *self == 0
    }
}

/// The columns one contract keeps for its queue.
pub trait ExpiryQueueStore<'storage>: BinTreeStorage {
    type Entry: QueueEntry;

    /// This map counts all slots allocated for a day. The queue clears freed slots without moving the remaining entries.
    fn day_len(&self) -> &Map<'storage, u32, u32>;
    fn day_live(&self) -> &Map<'storage, u32, u32>;
    /// [`slot_key`] -> entry.
    fn day_at(&self) -> &Map<'storage, B256, Self::Entry>;
    /// Entry -> [`pack_slot`]. 0 means not queued.
    fn entry_slot(&self) -> &Map<'storage, Self::Entry, u64>;
    fn entry_deadline(&self) -> &Map<'storage, Self::Entry, u64>;
    fn sweep_day(&self) -> &Value<'storage, u32>;
    /// [`pack_cursor`] of where the held walk resumes.
    fn sweep_cursor(&self) -> &Value<'storage, u64>;
}

/// This function returns the deadline's UTC day, counted from the Unix epoch, within the bitmap trie's 24-bit limit.
pub fn deadline_day(timestamp: u64) -> Result<u32> {
    let day = timestamp / SECONDS_PER_DAY;
    if day > u64::from(MAX_BIN_ID) {
        return Err(PrecompileError::Revert(
            "expiry day exceeds 24-bit range".into(),
        ));
    }
    // The check above proves this conversion fits in both u32 and the trie.
    u32::try_from(day).map_err(|_| PrecompileError::Revert("expiry day exceeds u32".into()))
}

/// This function returns the closing timestamp of a UTC day counted from the Unix epoch, including the maximum supported day.
pub const fn day_end(day: u32) -> u64 {
    (day as u64 + 1) * SECONDS_PER_DAY
}

/// This function encodes a supported 24-bit day and any slot as a nonzero location.
/// Adding one to the day distinguishes day zero, slot zero from an absent entry.
pub const fn pack_slot(day: u32, slot: u32) -> u64 {
    ((day as u64 + 1) << 32) | slot as u64
}

/// This function decodes a nonzero location from [`pack_slot`].
pub const fn unpack_slot(packed: u64) -> (u32, u32) {
    (
        ((packed >> 32) as u32).wrapping_sub(1),
        (packed & 0xffff_ffff) as u32,
    )
}

/// This function encodes the slot and member index where an interrupted sweep resumes.
/// Members at or above that index already failed in this pass. Zero starts from the highest member index.
pub const fn pack_cursor(slot: u32, member: u32) -> u64 {
    ((slot as u64) << 32) | member as u64
}

pub const fn unpack_cursor(packed: u64) -> (u32, u32) {
    ((packed >> 32) as u32, (packed & 0xffff_ffff) as u32)
}

pub fn slot_key(day: u32, slot: u32) -> B256 {
    let mut buf = [0u8; 8];
    buf[0..4].copy_from_slice(&day.to_be_bytes());
    buf[4..8].copy_from_slice(&slot.to_be_bytes());
    keccak256(buf)
}

/// This function appends `entry` to `day` and records its slot.
fn place<'s, Q: ExpiryQueueStore<'s>>(queue: &Q, entry: Q::Entry, day: u32) -> Result<()> {
    if day > MAX_BIN_ID || entry.is_vacant() {
        return Err(PrecompileError::Revert(
            "invalid expiry day or vacant entry".into(),
        ));
    }
    let slot = queue.day_len().read(&day)?;
    let len = slot
        .checked_add(1)
        .ok_or_else(|| PrecompileError::Revert("expiry day slots exhausted".into()))?;
    let live = queue.day_live().read(&day)?;
    let next_live = live
        .checked_add(1)
        .ok_or_else(|| PrecompileError::Revert("expiry day live count exhausted".into()))?;
    queue.day_at().write(&slot_key(day, slot), entry)?;
    queue.day_len().write(&day, len)?;
    queue.entry_slot().write(&entry, pack_slot(day, slot))?;
    queue.day_live().write(&day, next_live)?;
    if live == 0 {
        tree_math::add(queue, day)?;
    }
    Ok(())
}

/// This function adds `entry` to its deadline day without changing the exact deadline.
pub fn push<'s, Q: ExpiryQueueStore<'s>>(queue: &Q, entry: Q::Entry, deadline: u64) -> Result<()> {
    place(queue, entry, deadline_day(deadline)?)?;
    queue.entry_deadline().write(&entry, deadline)
}

/// Drops `entry` and its deadline from the queue.
pub fn remove<'s, Q: ExpiryQueueStore<'s>>(queue: &Q, entry: Q::Entry) -> Result<()> {
    let packed = queue.entry_slot().read(&entry)?;
    if packed != 0 {
        let (day, slot) = unpack_slot(packed);
        release(queue, day, slot, entry)?;
    }
    queue.entry_slot().clear(&entry)?;
    queue.entry_deadline().clear(&entry)
}

/// This function moves `entry` to `day`. Its deadline does not change.
fn retarget<'s, Q: ExpiryQueueStore<'s>>(queue: &Q, entry: Q::Entry, day: u32) -> Result<()> {
    let packed = queue.entry_slot().read(&entry)?;
    if packed != 0 {
        let (old_day, old_slot) = unpack_slot(packed);
        release(queue, old_day, old_slot, entry)?;
    }
    place(queue, entry, day)
}

/// This function frees one slot. It removes the day from the queue when no entries remain.
fn release<'s, Q: ExpiryQueueStore<'s>>(
    queue: &Q,
    day: u32,
    slot: u32,
    entry: Q::Entry,
) -> Result<()> {
    if day > MAX_BIN_ID {
        return Err(PrecompileError::Fatal("invalid stored expiry day".into()));
    }
    let key = slot_key(day, slot);
    if queue.day_at().read(&key)? != entry {
        return Ok(());
    }
    let live = queue
        .day_live()
        .read(&day)?
        .checked_sub(1)
        .ok_or_else(|| PrecompileError::Fatal("expiry day live count underflow".into()))?;
    queue.day_at().clear(&key)?;
    if live == 0 {
        // Clear the cursor so new entries for this day cannot inherit an outdated position.
        return retire_day(queue, day);
    }
    queue.day_live().write(&day, live)
}

pub fn entry_at<'s, Q: ExpiryQueueStore<'s>>(
    queue: &Q,
    day: u32,
    slot: u32,
) -> Result<Option<Q::Entry>> {
    let entry = queue.day_at().read(&slot_key(day, slot))?;
    Ok((!entry.is_vacant()).then_some(entry))
}

pub fn first_day<'s, Q: ExpiryQueueStore<'s>>(queue: &Q) -> Result<Option<u32>> {
    tree_math::find_first_left_inclusive(queue, 0)
}

/// Reports whether a closed scheduling day needs inspection, without walking entries.
/// Retry days, holes, and future-deadline leftovers use the same cutoff as [`sweep`].
pub fn has_cleanup_work<'s, Q: ExpiryQueueStore<'s>>(queue: &Q, now: u64) -> Result<bool> {
    let Some(closed_timestamp) = now.checked_sub(SECONDS_PER_DAY) else {
        return Ok(false);
    };
    let cutoff = deadline_day(closed_timestamp)?;
    Ok(first_day(queue)?.is_some_and(|day| day <= cutoff))
}

fn retire_day<'s, Q: ExpiryQueueStore<'s>>(queue: &Q, day: u32) -> Result<()> {
    queue.day_len().clear(&day)?;
    queue.day_live().clear(&day)?;
    tree_math::remove(queue, day)?;
    if queue.sweep_day().read()? == day {
        queue.sweep_day().write(0)?;
        queue.sweep_cursor().write(0)?;
    }
    Ok(())
}

/// This enum reports the action a right requires for a due entry.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Due {
    /// Expire its members.
    Expire,
    /// The sweep removes the entry because no members remain to expire.
    Drop,
    /// The sweep defers the entry to a later day.
    Wait,
}

/// The sweep expires each member within a separate checkpoint.
/// A deterministic failure retains the member. The sweep defers the entry after it attempts every member.
/// When the sweep exhausts its budget or gas, it preserves the cursor below previously processed members.
/// A node-local error fails the block.
pub trait ExpiryHandler<E> {
    type Member: Copy;

    fn due(&mut self, entry: E) -> Result<Due>;
    fn member_count(&self, entry: E) -> Result<u32>;
    fn member_at(&self, entry: E, index: u32) -> Result<Self::Member>;
    /// Expires `member` and takes it out of the entry.
    fn expire_member(&mut self, entry: E, member: Self::Member) -> Result<()>;
    fn classify(&self, error: &PrecompileError) -> SweepFailure {
        error.sweep_failure()
    }
    /// Reports that the entry waits until `retry_at`.
    fn deferred(&mut self, entry: E, retry_at: u64) -> Result<()>;
}

/// This function runs [`sweep`] with a separate budget for one block.
pub fn sweep_block<'s, Q, H>(
    queue: &Q,
    ctx: &crate::block::BlockRuntimeContext<'s>,
    handler: &mut H,
) -> Result<Progress>
where
    Q: ExpiryQueueStore<'s>,
    H: ExpiryHandler<Q::Entry>,
{
    sweep(
        queue,
        &ctx.storage,
        ctx.block.timestamp,
        &mut SweepBudget::per_block(),
        handler,
    )
}

/// This function resumes the selected deadline day with the caller's shared allowance for the block.
pub fn sweep_day<'s, Q, H>(
    queue: &Q,
    ctx: &crate::block::BlockRuntimeContext<'s>,
    through_day: u32,
    budget: &mut SweepBudget,
    handler: &mut H,
) -> Result<Progress>
where
    Q: ExpiryQueueStore<'s>,
    H: ExpiryHandler<Q::Entry>,
{
    sweep_through(
        queue,
        &ctx.storage,
        SweepTime {
            now: ctx.block.timestamp,
            through_day,
        },
        budget,
        handler,
    )
}

/// This function removes already-accounted records and stores the separate cleanup allowance within one checkpoint.
/// Repeated calls at the same block height cannot reset the allowance.
pub fn sweep_cleanup<'s, Q, H>(
    queue: &Q,
    ctx: &crate::block::BlockRuntimeContext<'s>,
    saved_budget: &Value<'s, U256>,
    handler: &mut H,
) -> Result<Progress>
where
    Q: ExpiryQueueStore<'s>,
    H: ExpiryHandler<Q::Entry>,
{
    ctx.storage.with_checkpoint(|| {
        let mut allowance =
            BlockAllowance::for_block(saved_budget.read()?, ctx.block.block_number, 0)?;
        let progress = sweep(
            queue,
            &ctx.storage,
            ctx.block.timestamp,
            &mut allowance.budget,
            handler,
        )?;
        saved_budget.write(allowance.pack())?;
        Ok(progress)
    })
}

/// This function processes entries through the last closed UTC day. The sweep does not visit an open day.
pub fn sweep<'s, Q, H>(
    queue: &Q,
    storage: &StorageHandle<'s>,
    now: u64,
    budget: &mut SweepBudget,
    handler: &mut H,
) -> Result<Progress>
where
    Q: ExpiryQueueStore<'s>,
    H: ExpiryHandler<Q::Entry>,
{
    let Some(closed_timestamp) = now.checked_sub(SECONDS_PER_DAY) else {
        return Ok(Progress::Complete);
    };
    sweep_through(
        queue,
        storage,
        SweepTime {
            now,
            through_day: deadline_day(closed_timestamp)?,
        },
        budget,
        handler,
    )
}

/// Implements [`BinTreeStorage`] and [`ExpiryQueueStore`] for `Adapter(&contract)`.
#[macro_export]
macro_rules! impl_expiry_queue {
    ($adapter:ident<$entry:ty> {
        root: $root:ident,
        mid: $mid:ident,
        leaf: $leaf:ident,
        len: $len:ident,
        live: $live:ident,
        at: $at:ident,
        slot: $slot:ident,
        deadline: $deadline:ident,
        sweep_day: $sweep_day:ident,
        cursor: $cursor:ident $(,)?
    }) => {
        $crate::impl_bin_tree_storage!($adapter {
            root: $root,
            mid: $mid,
            leaf: $leaf
        });

        impl<'s> $crate::expiry_queue::ExpiryQueueStore<'s> for $adapter<'_, 's> {
            type Entry = $entry;
            fn day_len(&self) -> &$crate::storage::dsl::Map<'s, u32, u32> {
                &self.0.$len
            }
            fn day_live(&self) -> &$crate::storage::dsl::Map<'s, u32, u32> {
                &self.0.$live
            }
            fn day_at(&self) -> &$crate::storage::dsl::Map<'s, ::alloy_primitives::B256, $entry> {
                &self.0.$at
            }
            fn entry_slot(&self) -> &$crate::storage::dsl::Map<'s, $entry, u64> {
                &self.0.$slot
            }
            fn entry_deadline(&self) -> &$crate::storage::dsl::Map<'s, $entry, u64> {
                &self.0.$deadline
            }
            fn sweep_day(&self) -> &$crate::storage::dsl::Value<'s, u32> {
                &self.0.$sweep_day
            }
            fn sweep_cursor(&self) -> &$crate::storage::dsl::Value<'s, u64> {
                &self.0.$cursor
            }
        }
    };
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::storage::hashmap::HashMapStorageProvider;
    use alloy_primitives::{address, Address};

    const CONTRACT: Address = address!("0x0000000000000000000000000000000000001003");
    const DAY: u64 = SECONDS_PER_DAY;

    struct Columns<'s> {
        root: Value<'s, U256>,
        mid: Map<'s, u32, U256>,
        leaf: Map<'s, u32, U256>,
        len: Map<'s, u32, u32>,
        live: Map<'s, u32, u32>,
        at: Map<'s, B256, U256>,
        slot: Map<'s, U256, u64>,
        deadline: Map<'s, U256, u64>,
        sweep_day: Value<'s, u32>,
        cursor: Value<'s, u64>,
    }

    impl<'s> Columns<'s> {
        fn new(storage: StorageHandle<'s>) -> Self {
            let slot = |n: u64| U256::from(n);
            Self {
                root: Value::new(slot(0), CONTRACT, storage.clone()),
                mid: Map::new(slot(1), CONTRACT, storage.clone()),
                leaf: Map::new(slot(2), CONTRACT, storage.clone()),
                len: Map::new(slot(3), CONTRACT, storage.clone()),
                live: Map::new(slot(4), CONTRACT, storage.clone()),
                at: Map::new(slot(5), CONTRACT, storage.clone()),
                slot: Map::new(slot(6), CONTRACT, storage.clone()),
                deadline: Map::new(slot(7), CONTRACT, storage.clone()),
                sweep_day: Value::new(slot(8), CONTRACT, storage.clone()),
                cursor: Value::new(slot(9), CONTRACT, storage),
            }
        }
    }

    struct Queue<'a, 's>(&'a Columns<'s>);
    crate::impl_expiry_queue!(Queue<U256> {
        root: root, mid: mid, leaf: leaf, len: len, live: live, at: at,
        slot: slot, deadline: deadline, sweep_day: sweep_day, cursor: cursor,
    });

    struct Recorder {
        expired: Vec<U256>,
        deferred: Vec<(U256, u64)>,
        out_of_gas_on: Vec<U256>,
        refused: Vec<U256>,
        due: Due,
    }

    impl ExpiryHandler<U256> for Recorder {
        type Member = U256;
        fn due(&mut self, _: U256) -> Result<Due> {
            Ok(self.due)
        }
        fn member_count(&self, _: U256) -> Result<u32> {
            Ok(1)
        }
        fn member_at(&self, entry: U256, _: u32) -> Result<U256> {
            Ok(entry)
        }
        fn expire_member(&mut self, entry: U256, _: U256) -> Result<()> {
            if self.out_of_gas_on.contains(&entry) {
                return Err(PrecompileError::OutOfGas);
            }
            if self.refused.contains(&entry) {
                return Err(PrecompileError::Revert("refused".into()));
            }
            self.expired.push(entry);
            Ok(())
        }
        fn deferred(&mut self, entry: U256, retry_at: u64) -> Result<()> {
            self.deferred.push((entry, retry_at));
            Ok(())
        }
    }

    fn with_queue(test: impl for<'s> FnOnce(&Queue<'_, 's>, &StorageHandle<'s>)) {
        let mut provider = HashMapStorageProvider::new(1);
        StorageHandle::enter(&mut provider, |storage| {
            let columns = Columns::new(storage.clone());
            test(&Queue(&columns), &storage);
        });
    }

    fn recorder() -> Recorder {
        Recorder {
            expired: Vec::new(),
            deferred: Vec::new(),
            out_of_gas_on: Vec::new(),
            refused: Vec::new(),
            due: Due::Expire,
        }
    }

    fn id(n: u64) -> U256 {
        U256::from(n)
    }

    #[test]
    fn cleanup_work_uses_scheduling_days_including_holes_and_retries() {
        with_queue(|queue, storage| {
            assert!(!has_cleanup_work(queue, 0).unwrap());
            assert!(!has_cleanup_work(queue, 11 * DAY).unwrap());
            push(queue, id(1), 10 * DAY).unwrap();
            push(queue, id(2), 10 * DAY).unwrap();
            remove(queue, id(1)).unwrap();
            // The indexed day still requires inspection even if its remaining deadline moved.
            queue.entry_deadline().write(&id(2), 20 * DAY).unwrap();
            assert!(!has_cleanup_work(queue, 11 * DAY - 1).unwrap());
            assert!(has_cleanup_work(queue, 11 * DAY).unwrap());
            let mut handler = recorder();
            run(
                queue,
                storage,
                11 * DAY,
                &mut SweepBudget::new(10, 10),
                &mut handler,
            );
            assert_eq!(first_day(queue).unwrap(), Some(20));
            assert!(!has_cleanup_work(queue, 11 * DAY).unwrap());
            remove(queue, id(2)).unwrap();
            push(queue, id(3), 10 * DAY).unwrap();
            handler.refused.push(id(3));
            run(
                queue,
                storage,
                12 * DAY + 30,
                &mut SweepBudget::new(10, 10),
                &mut handler,
            );
            assert_eq!(first_day(queue).unwrap(), Some(12));
            assert!(!has_cleanup_work(queue, 13 * DAY - 1).unwrap());
            assert!(has_cleanup_work(queue, 13 * DAY).unwrap());
            assert!(has_cleanup_work(queue, u64::MAX).is_err());
        });
    }

    #[test]
    fn cleanup_work_queries_do_not_write_queue_or_cursor_state() {
        let mut provider = HashMapStorageProvider::new(1);
        StorageHandle::enter(&mut provider, |storage| {
            let columns = Columns::new(storage);
            push(&Queue(&columns), id(1), 10 * DAY).unwrap();
        });
        let before = provider.storage.clone();
        provider.set_static(true);
        StorageHandle::enter(&mut provider, |storage| {
            let columns = Columns::new(storage);
            let queue = Queue(&columns);
            assert!(!has_cleanup_work(&queue, 11 * DAY - 1).unwrap());
            assert!(has_cleanup_work(&queue, 11 * DAY).unwrap());
        });
        assert_eq!(provider.storage, before);
        assert!(provider.events.is_empty());
    }

    fn run<'s>(
        queue: &Queue<'_, 's>,
        storage: &StorageHandle<'s>,
        now: u64,
        budget: &mut SweepBudget,
        handler: &mut Recorder,
    ) -> Progress {
        sweep(queue, storage, now, budget, handler).unwrap()
    }

    #[test]
    fn removing_the_last_entry_retires_its_day_and_cursor() {
        with_queue(|queue, _| {
            push(queue, id(1), 10 * DAY + 5).unwrap();
            push(queue, id(2), 10 * DAY + 9).unwrap();
            queue.sweep_day().write(10).unwrap();
            queue.sweep_cursor().write(1).unwrap();
            remove(queue, id(1)).unwrap();
            assert_eq!(queue.day_live().read(&10).unwrap(), 1);
            assert_eq!(entry_at(queue, 10, 0).unwrap(), None);
            remove(queue, id(2)).unwrap();
            assert_eq!(first_day(queue).unwrap(), None);
            assert_eq!(queue.day_len().read(&10).unwrap(), 0);
            assert_eq!(queue.sweep_day().read().unwrap(), 0);
            assert_eq!(queue.sweep_cursor().read().unwrap(), 0);
            assert_eq!(queue.entry_deadline().read(&id(1)).unwrap(), 0);
        });
    }

    #[test]
    fn day_closure_not_the_deadline_or_next_hour_makes_work_eligible() {
        with_queue(|queue, storage| {
            let deadline = 10 * DAY + 10 * 3_600;
            push(queue, id(1), deadline).unwrap();
            push(queue, id(2), 11 * DAY).unwrap();
            let mut handler = recorder();
            let mut budget = SweepBudget::new(10, 10);
            for now in [deadline, deadline + 1, deadline + 3_600, 11 * DAY - 1] {
                assert_eq!(
                    run(queue, storage, now, &mut budget, &mut handler),
                    Progress::Complete
                );
            }
            assert!(handler.expired.is_empty());
            assert_eq!(budget.visits_left(), 10);
            assert_eq!(
                run(queue, storage, 11 * DAY, &mut budget, &mut handler),
                Progress::Complete
            );
            assert_eq!(handler.expired, vec![id(1)]);
            assert_eq!(first_day(queue).unwrap(), Some(11));
            assert_eq!(queue.entry_deadline().read(&id(2)).unwrap(), 11 * DAY);
        });
    }

    #[test]
    fn catch_up_stops_at_the_pinned_cutoff_even_with_spare_budget() {
        with_queue(|queue, storage| {
            for day in [12, 10, 11] {
                push(queue, id(day), day * DAY).unwrap();
            }
            let mut handler = recorder();
            let mut budget = SweepBudget::new(10, 10);
            assert_eq!(
                sweep_through(
                    queue,
                    storage,
                    SweepTime {
                        now: 20 * DAY,
                        through_day: 11
                    },
                    &mut budget,
                    &mut handler,
                )
                .unwrap(),
                Progress::Complete
            );
            assert_eq!(handler.expired, vec![id(10), id(11)]);
            assert_eq!(first_day(queue).unwrap(), Some(12));
            assert_eq!((budget.visits_left(), budget.writes_left()), (8, 8));
            assert_eq!(
                sweep_through(
                    queue,
                    storage,
                    SweepTime {
                        now: 12 * DAY,
                        through_day: 12
                    },
                    &mut budget,
                    &mut handler,
                )
                .unwrap(),
                Progress::Pending
            );
        });
    }

    #[test]
    fn spent_budget_and_gas_resume_the_exact_entry() {
        with_queue(|queue, storage| {
            for n in 1..=3 {
                push(queue, id(n), 10 * DAY).unwrap();
            }
            let mut handler = recorder();
            assert_eq!(
                run(
                    queue,
                    storage,
                    11 * DAY,
                    &mut SweepBudget::new(1, 10),
                    &mut handler
                ),
                Progress::Pending
            );
            assert_eq!(queue.sweep_cursor().read().unwrap(), pack_cursor(1, 0));
            handler.out_of_gas_on.push(id(2));
            let mut stopped_budget = SweepBudget::new(10, 10);
            assert_eq!(
                run(queue, storage, 11 * DAY, &mut stopped_budget, &mut handler),
                Progress::Pending
            );
            assert_eq!(queue.sweep_cursor().read().unwrap(), pack_cursor(1, 1));
            assert_eq!(handler.expired, vec![id(1)]);
            handler.out_of_gas_on.clear();
            assert_eq!(
                (stopped_budget.visits_left(), stopped_budget.writes_left()),
                (0, 0)
            );
            assert_eq!(
                run(queue, storage, 11 * DAY, &mut stopped_budget, &mut handler),
                Progress::Pending
            );
            assert_eq!(handler.expired, vec![id(1)]);
            assert_eq!(
                run(
                    queue,
                    storage,
                    11 * DAY,
                    &mut SweepBudget::new(2, 10),
                    &mut handler
                ),
                Progress::Complete
            );
            assert_eq!(handler.expired, vec![id(1), id(2), id(3)]);
        });
    }

    #[test]
    fn refused_members_retry_at_the_next_midnight_not_one_day_later() {
        with_queue(|queue, storage| {
            push(queue, id(1), 10 * DAY + 5).unwrap();
            push(queue, id(2), 10 * DAY + 5).unwrap();
            let mut handler = recorder();
            handler.refused.push(id(1));
            assert_eq!(
                run(
                    queue,
                    storage,
                    12 * DAY + 30,
                    &mut SweepBudget::new(10, 10),
                    &mut handler
                ),
                Progress::Complete
            );
            assert_eq!(handler.expired, vec![id(2)]);
            assert_eq!(handler.deferred, vec![(id(1), 13 * DAY)]);
            assert_eq!(first_day(queue).unwrap(), Some(12));
            assert_eq!(queue.entry_deadline().read(&id(1)).unwrap(), 10 * DAY + 5);
            run(
                queue,
                storage,
                13 * DAY - 1,
                &mut SweepBudget::new(10, 10),
                &mut handler,
            );
            assert_eq!(handler.deferred.len(), 1);
            handler.refused.clear();
            run(
                queue,
                storage,
                13 * DAY,
                &mut SweepBudget::new(10, 10),
                &mut handler,
            );
            assert_eq!(handler.expired, vec![id(2), id(1)]);
        });
    }

    #[test]
    fn holes_and_future_leftovers_each_consume_one_visit() {
        with_queue(|queue, storage| {
            for n in 1..=5 {
                push(queue, id(n), 10 * DAY).unwrap();
            }
            for n in 1..=3 {
                remove(queue, id(n)).unwrap();
            }
            queue.entry_deadline().write(&id(4), 20 * DAY).unwrap();
            let mut handler = recorder();
            let mut budget = SweepBudget::new(3, 10);
            assert_eq!(
                run(queue, storage, 11 * DAY, &mut budget, &mut handler),
                Progress::Pending
            );
            assert_eq!(budget.visits_left(), 0);
            assert_eq!(queue.sweep_cursor().read().unwrap(), pack_cursor(3, 0));
            assert!(handler.deferred.is_empty());
            assert_eq!(
                run(
                    queue,
                    storage,
                    11 * DAY,
                    &mut SweepBudget::new(1, 10),
                    &mut handler
                ),
                Progress::Pending
            );
            assert_eq!(handler.deferred, vec![(id(4), 21 * DAY)]);
            assert_eq!(queue.entry_deadline().read(&id(4)).unwrap(), 20 * DAY);
            assert_eq!(queue.sweep_cursor().read().unwrap(), pack_cursor(4, 0));
            assert_eq!(
                run(
                    queue,
                    storage,
                    11 * DAY,
                    &mut SweepBudget::new(1, 10),
                    &mut handler
                ),
                Progress::Complete
            );
            assert_eq!(handler.expired, vec![id(5)]);
            assert_eq!(first_day(queue).unwrap(), Some(20));
        });
    }

    #[test]
    fn empty_entries_drop_and_waiting_entries_defer_without_member_writes() {
        with_queue(|queue, storage| {
            push(queue, id(1), 10 * DAY).unwrap();
            let mut handler = recorder();
            handler.due = Due::Drop;
            run(
                queue,
                storage,
                11 * DAY,
                &mut SweepBudget::new(10, 0),
                &mut handler,
            );
            assert_eq!(queue.entry_slot().read(&id(1)).unwrap(), 0);
            push(queue, id(2), 10 * DAY).unwrap();
            handler.due = Due::Wait;
            run(
                queue,
                storage,
                11 * DAY,
                &mut SweepBudget::new(10, 0),
                &mut handler,
            );
            assert_eq!(handler.deferred, vec![(id(2), 12 * DAY)]);
            assert_eq!(first_day(queue).unwrap(), Some(11));
        });
    }

    #[test]
    fn day_and_location_boundaries_do_not_alias_zero() {
        assert_eq!(deadline_day(0).unwrap(), 0);
        assert_eq!(deadline_day(DAY - 1).unwrap(), 0);
        assert_eq!(deadline_day(DAY).unwrap(), 1);
        assert_eq!(deadline_day(day_end(MAX_BIN_ID) - 1).unwrap(), MAX_BIN_ID);
        assert!(deadline_day(day_end(MAX_BIN_ID)).is_err());
        assert!(deadline_day(u64::MAX).is_err());
        for day in [0, MAX_BIN_ID] {
            for slot in [0, u32::MAX] {
                assert_ne!(pack_slot(day, slot), 0);
                assert_eq!(unpack_slot(pack_slot(day, slot)), (day, slot));
            }
        }
        with_queue(|queue, storage| {
            assert!(push(queue, U256::ZERO, 0).is_err());
            assert!(push(queue, id(2), u64::MAX).is_err());
            assert_eq!(first_day(queue).unwrap(), None);
            push(queue, id(1), 0).unwrap();
            assert_ne!(queue.entry_slot().read(&id(1)).unwrap(), 0);
            let mut handler = recorder();
            assert_eq!(
                run(
                    queue,
                    storage,
                    DAY,
                    &mut SweepBudget::new(1, 1),
                    &mut handler
                ),
                Progress::Complete
            );
            assert_eq!(handler.expired, vec![id(1)]);
            push(queue, id(2), day_end(MAX_BIN_ID) - 1).unwrap();
            assert_eq!(
                run(
                    queue,
                    storage,
                    day_end(MAX_BIN_ID),
                    &mut SweepBudget::new(1, 1),
                    &mut handler
                ),
                Progress::Complete
            );
            assert_eq!(handler.expired, vec![id(1), id(2)]);
        });
    }

    #[test]
    fn exhausted_counts_fail_before_writing_a_slot() {
        with_queue(|queue, _| {
            for (len, live) in [(u32::MAX, 0), (0, u32::MAX)] {
                queue.day_len().write(&10, len).unwrap();
                queue.day_live().write(&10, live).unwrap();
                assert!(push(queue, id(1), 10 * DAY).is_err());
                assert_eq!(queue.entry_slot().read(&id(1)).unwrap(), 0);
                assert_eq!(entry_at(queue, 10, len).unwrap(), None);
            }
        });
    }

    struct CheckpointHandler<'s> {
        state: Value<'s, u32>,
        member_error: Option<PrecompileError>,
        defer_error: bool,
    }

    impl ExpiryHandler<U256> for CheckpointHandler<'_> {
        type Member = ();

        fn due(&mut self, _: U256) -> Result<Due> {
            Ok(Due::Expire)
        }

        fn member_count(&self, _: U256) -> Result<u32> {
            Ok(1)
        }

        fn member_at(&self, _: U256, _: u32) -> Result<()> {
            Ok(())
        }

        fn expire_member(&mut self, _: U256, _: ()) -> Result<()> {
            self.state.write(1)?;
            match self.member_error.take() {
                Some(error) => Err(error),
                None => Ok(()),
            }
        }

        fn deferred(&mut self, _: U256, _: u64) -> Result<()> {
            if self.defer_error {
                self.state.write(2)?;
                return Err(PrecompileError::Storage("injected defer failure".into()));
            }
            Ok(())
        }
    }

    #[test]
    fn cleanup_persists_its_allowance_and_rolls_back_a_failed_continuation() {
        with_queue(|queue, storage| {
            use crate::block::{BlockContext, BlockRuntimeContext};
            use crate::sweep_budget::{SWEEP_VISITS_PER_BLOCK, SWEEP_WRITES_PER_BLOCK};

            push(queue, id(1), 10 * DAY).unwrap();
            push(queue, id(2), 10 * DAY).unwrap();
            let saved = Value::new(id(20), CONTRACT, storage.clone());
            saved
                .write(
                    BlockAllowance {
                        height: 4,
                        day: 0,
                        budget: SweepBudget::new(SWEEP_VISITS_PER_BLOCK, 1),
                    }
                    .pack(),
                )
                .unwrap();
            let ctx = BlockRuntimeContext::new(
                BlockContext::empty_for_tests(4, 11 * DAY, 1),
                storage.clone(),
            );
            let mut handler = recorder();
            assert_eq!(
                sweep_cleanup(queue, &ctx, &saved, &mut handler).unwrap(),
                Progress::Pending
            );
            assert_eq!(handler.expired, vec![id(1)]);
            assert_eq!(
                sweep_cleanup(queue, &ctx, &saved, &mut handler).unwrap(),
                Progress::Pending
            );
            assert_eq!(
                handler.expired,
                vec![id(1)],
                "same-height work cannot refill writes"
            );
            let before = saved.read().unwrap();
            let cursor = queue.sweep_cursor().read().unwrap();

            let ctx = BlockRuntimeContext::new(
                BlockContext::empty_for_tests(5, 11 * DAY, 1),
                storage.clone(),
            );
            let mut handler = CheckpointHandler {
                state: Value::new(id(30), CONTRACT, storage.clone()),
                member_error: Some(PrecompileError::Storage("injected cleanup failure".into())),
                defer_error: false,
            };
            assert!(matches!(
                sweep_cleanup(queue, &ctx, &saved, &mut handler),
                Err(PrecompileError::Storage(_))
            ));
            assert_eq!(handler.state.read().unwrap(), 0);
            assert_eq!(saved.read().unwrap(), before);
            assert_eq!(queue.sweep_cursor().read().unwrap(), cursor);
            assert_eq!(entry_at(queue, 10, 1).unwrap(), Some(id(2)));

            assert_eq!(
                sweep_cleanup(queue, &ctx, &saved, &mut handler).unwrap(),
                Progress::Complete
            );
            assert_eq!(first_day(queue).unwrap(), None);
            let allowance = BlockAllowance::unpack(saved.read().unwrap())
                .unwrap()
                .unwrap();
            assert_eq!(allowance.height, 5);
            assert_eq!(allowance.budget.writes_left(), SWEEP_WRITES_PER_BLOCK - 1);
        });
    }

    #[test]
    fn member_failures_roll_back_and_node_local_errors_propagate() {
        with_queue(|queue, storage| {
            push(queue, id(1), 10 * DAY + 5).unwrap();
            let mut handler = CheckpointHandler {
                state: Value::new(id(30), CONTRACT, storage.clone()),
                member_error: Some(PrecompileError::Revert("refused".into())),
                defer_error: false,
            };
            assert_eq!(
                sweep(
                    queue,
                    storage,
                    11 * DAY,
                    &mut SweepBudget::new(1, 1),
                    &mut handler
                )
                .unwrap(),
                Progress::Complete
            );
            assert_eq!(handler.state.read().unwrap(), 0);
            assert_eq!(first_day(queue).unwrap(), Some(11));
            assert_eq!(queue.entry_deadline().read(&id(1)).unwrap(), 10 * DAY + 5);

            handler.member_error = Some(PrecompileError::Storage("injected member failure".into()));
            assert!(matches!(
                sweep(
                    queue,
                    storage,
                    12 * DAY,
                    &mut SweepBudget::new(1, 1),
                    &mut handler
                ),
                Err(PrecompileError::Storage(_))
            ));
            assert_eq!(handler.state.read().unwrap(), 0);
            assert_eq!(first_day(queue).unwrap(), Some(11));

            handler.member_error = Some(PrecompileError::Revert("refused again".into()));
            handler.defer_error = true;
            assert!(matches!(
                sweep(
                    queue,
                    storage,
                    12 * DAY,
                    &mut SweepBudget::new(1, 1),
                    &mut handler
                ),
                Err(PrecompileError::Storage(_))
            ));
            // One checkpoint covers the callback, the changed scheduling day, and the trie updates.
            assert_eq!(handler.state.read().unwrap(), 0);
            assert_eq!(first_day(queue).unwrap(), Some(11));
            assert_eq!(entry_at(queue, 11, 0).unwrap(), Some(id(1)));
            assert_eq!(
                unpack_slot(queue.entry_slot().read(&id(1)).unwrap()),
                (11, 0)
            );
            assert_eq!(queue.entry_deadline().read(&id(1)).unwrap(), 10 * DAY + 5);
        });
    }

    struct Members {
        members: Vec<u64>,
        failing: Vec<u64>,
        expired: Vec<u64>,
        deferred: u32,
    }

    impl ExpiryHandler<U256> for Members {
        type Member = u32;
        fn due(&mut self, _: U256) -> Result<Due> {
            Ok(if self.members.is_empty() {
                Due::Drop
            } else {
                Due::Expire
            })
        }
        fn member_count(&self, _: U256) -> Result<u32> {
            Ok(u32::try_from(self.members.len()).unwrap())
        }
        fn member_at(&self, _: U256, index: u32) -> Result<u32> {
            Ok(index)
        }
        fn expire_member(&mut self, _: U256, index: u32) -> Result<()> {
            let member = self.members[index as usize];
            if self.failing.contains(&member) {
                return Err(PrecompileError::Revert("refused".into()));
            }
            self.members.swap_remove(index as usize);
            self.expired.push(member);
            Ok(())
        }
        fn deferred(&mut self, _: U256, _: u64) -> Result<()> {
            self.deferred += 1;
            Ok(())
        }
    }

    #[test]
    fn failed_members_wider_than_the_budget_are_tried_once_per_pass() {
        with_queue(|queue, storage| {
            push(queue, id(1), 10 * DAY).unwrap();
            let mut handler = Members {
                members: (0..10).collect(),
                failing: vec![7, 8, 9],
                expired: Vec::new(),
                deferred: 0,
            };
            for _ in 0..4 {
                assert_eq!(
                    sweep(
                        queue,
                        storage,
                        11 * DAY,
                        &mut SweepBudget::new(10, 2),
                        &mut handler
                    )
                    .unwrap(),
                    Progress::Pending
                );
            }
            assert_eq!(handler.expired.len(), 5);
            assert_eq!(handler.deferred, 0);
            assert_eq!(
                sweep(
                    queue,
                    storage,
                    11 * DAY,
                    &mut SweepBudget::new(10, 2),
                    &mut handler
                )
                .unwrap(),
                Progress::Complete
            );
            assert_eq!(handler.expired.len(), 7);
            assert_eq!(handler.deferred, 1);
            assert_eq!(first_day(queue).unwrap(), Some(11));
            assert_eq!(queue.sweep_cursor().read().unwrap(), 0);
        });
    }
}
